    groupExecutionsByPeriod(executions, groupBy) {
        const grouped = executions.reduce((acc, execution) => {
            let key;
            const date = new Date(execution.createdAt);
            switch (groupBy) {
                case 'day':
                    key = date.toISOString().split('T')[0];
                    break;
                case 'week':
                    const weekStart = new Date(date);
                    weekStart.setDate(date.getDate() - date.getDay());
                    key = weekStart.toISOString().split('T')[0];
                    break;
                case 'month':
                    key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                    break;
            }
            if (!acc[key]) {
                acc[key] = {
                    period: key,
                    executions: [],
                    totalExecutions: 0,
                    successfulExecutions: 0,
                    failedExecutions: 0,
                    totalTime: 0,
                    totalCost: 0,
                };
            }
            acc[key].executions.push(execution);
            acc[key].totalExecutions++;
            if (execution.status === execution_status_enum_1.ExecutionStatus.COMPLETED) {
                acc[key].successfulExecutions++;
            }
            else if (execution.status === execution_status_enum_1.ExecutionStatus.FAILED) {
                acc[key].failedExecutions++;
            }
            acc[key].totalTime += execution.executionTimeMs || 0;
            acc[key].totalCost += execution.cost || 0;
            return acc;
        }, {});
        return Object.values(grouped).map((group) => ({
            ...group,
            avgExecutionTime: group.totalExecutions > 0 ? group.totalTime / group.totalExecutions : 0,
            successRate: group.totalExecutions > 0 ? (group.successfulExecutions / group.totalExecutions) * 100 : 0,
            executions: undefined,
        }));
    }
    analyzeCallerPatterns(executions) {
        const patterns = executions.reduce((acc, execution) => {
            const callerType = execution.context?.callerType || 'unknown';
            const callerId = execution.context?.callerId || 'unknown';
            const key = `${callerType}:${callerId}`;
            if (!acc[key]) {
                acc[key] = {
                    callerType,
                    callerId,
                    totalExecutions: 0,
                    successfulExecutions: 0,
                    failedExecutions: 0,
                    totalTime: 0,
                    totalCost: 0,
                    lastExecution: null,
                };
            }
            acc[key].totalExecutions++;
            if (execution.status === execution_status_enum_1.ExecutionStatus.COMPLETED) {
                acc[key].successfulExecutions++;
            }
            else if (execution.status === execution_status_enum_1.ExecutionStatus.FAILED) {
                acc[key].failedExecutions++;
            }
            acc[key].totalTime += execution.executionTimeMs || 0;
            acc[key].totalCost += execution.cost || 0;
            acc[key].lastExecution = execution.createdAt;
            return acc;
        }, {});
        return Object.values(patterns)
            .map((pattern) => ({
            ...pattern,
            avgExecutionTime: pattern.totalExecutions > 0 ? pattern.totalTime / pattern.totalExecutions : 0,
            successRate: pattern.totalExecutions > 0
                ? (pattern.successfulExecutions / pattern.totalExecutions) * 100
                : 0,
        }))
            .sort((a, b) => b.totalExecutions - a.totalExecutions);
    }
    calculatePerformanceTrends(groupedData) {
        return groupedData.map((group, index) => {
            const prevGroup = index > 0 ? groupedData[index - 1] : null;
            return {
                period: group.period,
                executions: group.totalExecutions,
                successRate: group.successRate,
                avgExecutionTime: group.avgExecutionTime,
                totalCost: group.totalCost,
                trends: prevGroup
                    ? {
                        executionChange: ((group.totalExecutions - prevGroup.totalExecutions) /
                            (prevGroup.totalExecutions || 1)) *
                            100,
                        successRateChange: group.successRate - prevGroup.successRate,
                        executionTimeChange: ((group.avgExecutionTime - prevGroup.avgExecutionTime) /
                            (prevGroup.avgExecutionTime || 1)) *
                            100,
                        costChange: ((group.totalCost - prevGroup.totalCost) / (prevGroup.totalCost || 1)) * 100,
                    }
                    : null,
            };
        });
    }
    analyzeErrorPatterns(executions) {
        const failedExecutions = executions.filter((e) => e.status === execution_status_enum_1.ExecutionStatus.FAILED && e.error);
        const errorCounts = failedExecutions.reduce((acc, execution) => {
            const error = execution.error || 'Unknown error';
            const errorType = this.categorizeError(error);
            if (!acc[errorType]) {
                acc[errorType] = {
                    errorType,
                    count: 0,
                    examples: [],
                    firstOccurrence: execution.createdAt,
                    lastOccurrence: execution.createdAt,
                };
            }
            acc[errorType].count++;
            if (acc[errorType].examples.length < 3) {
                acc[errorType].examples.push({
                    error: execution.error,
                    timestamp: execution.createdAt,
                    context: execution.context,
                });
            }
            if (execution.createdAt > acc[errorType].lastOccurrence) {
                acc[errorType].lastOccurrence = execution.createdAt;
            }
            return acc;
        }, {});
        return Object.values(errorCounts)
            .sort((a, b) => b.count - a.count)
            .slice(0, 10);
    }
    categorizeError(error) {
        const lowerError = error.toLowerCase();
        if (lowerError.includes('timeout') || lowerError.includes('etimedout')) {
            return 'Timeout Error';
        }
        if (lowerError.includes('network') ||
            lowerError.includes('enotfound') ||
            lowerError.includes('econnrefused')) {
            return 'Network Error';
        }
        if (lowerError.includes('401') || lowerError.includes('unauthorized')) {
            return 'Authentication Error';
        }
        if (lowerError.includes('403') || lowerError.includes('forbidden')) {
            return 'Authorization Error';
        }
        if (lowerError.includes('404') || lowerError.includes('not found')) {
            return 'Not Found Error';
        }
        if (lowerError.includes('429') || lowerError.includes('rate limit')) {
            return 'Rate Limit Error';
        }
        if (lowerError.includes('500') || lowerError.includes('internal server')) {
            return 'Server Error';
        }
        if (lowerError.includes('validation') || lowerError.includes('invalid')) {
            return 'Validation Error';
        }
        return 'Other Error';
    }
    extractAvailableVariables(definition, stepId) {
        const variables = [];
        if (definition?.steps && Array.isArray(definition.steps)) {
            definition.steps.forEach((step, index) => {
                if (!stepId ||
                    step.id === stepId ||
                    index < definition.steps.findIndex((s) => s.id === stepId)) {
                    if (step.outputs) {
                        variables.push(...Object.keys(step.outputs));
                    }
                    if (step.variables) {
                        variables.push(...Object.keys(step.variables));
                    }
                }
            });
        }
        if (definition?.variables) {
            variables.push(...Object.keys(definition.variables));
        }
        return [...new Set(variables)];
    }
